using RoseLynn.Writing;

namespace RoseLynn.PoC.UnitTests;

public sealed class RenovationPlanGeneratorTests
    : PoCGeneratorTestContainer<RenovationPlanGenerator, RenovationPlanGeneratorTests.GeneratorTest>
{
    public sealed class GeneratorTest : PoCGeneratorTest
    {
    }

    [Test]
    public async Task GeneratesRenovationPlanFieldsForDistinctAnnotatedMembers()
    {
        var generatedSources = new SourceCollection
        {
            ["Demo.Kitchen.RenovationPlan.g.cs"] = Utf8CSharpSource(
                """
// <auto-generated/>
namespace Demo;

partial class Kitchen
{
    public static readonly global::System.Collections.Generic.IReadOnlyList<string> sinkRenovationPlan = new string[] { "sink" };
    public static readonly global::System.Collections.Generic.IReadOnlyList<string> NameRenovationPlan = new string[] { "Name" };
    public static readonly global::System.Collections.Generic.IReadOnlyList<string> PaintRenovationPlan = new string[] { "Paint" };
    public static readonly global::System.Collections.Generic.IReadOnlyList<string> CrewRenovationPlan = new string[] { "Crew" };
}

"""),
        };

        await VerifyAsync(
            """
using RoseLynn.PoC.UnitTests;

namespace Demo;

[Renovate]
public partial class Kitchen
{
    private int sink;
    public string Name { get; set; } = "";
    public void Paint()
    {
    }

    public void Paint(int coats)
    {
    }

    public class Crew
    {
    }
}
""",
            generatedSources);
    }

    [Test]
    public async Task GeneratesNestedPartialDeclarationsForAnnotatedNestedTypes()
    {
        var generatedSources = new SourceCollection
        {
            ["Demo.House.Kitchen.RenovationPlan.g.cs"] = Utf8CSharpSource(
                """
// <auto-generated/>
namespace Demo;

partial class House
{
partial class Kitchen
{
    public static readonly global::System.Collections.Generic.IReadOnlyList<string> PaintRenovationPlan = new string[] { "Paint" };
}
}

"""),
        };

        await VerifyAsync(
            """
using RoseLynn.PoC.UnitTests;

namespace Demo;

public partial class House
{
    [Renovate]
    public partial class Kitchen
    {
        public void Paint()
        {
        }
    }
}
""",
            generatedSources);
    }

    [Test]
    public async Task DoesNotGenerateAnythingForNonPartialAnnotatedTypes()
    {
        await VerifyAsync(
            """
using RoseLynn.PoC.UnitTests;

namespace Demo;

[Renovate]
public class Kitchen
{
    public void Paint()
    {
    }
}
""",
            new SourceCollection());
    }
}
